// Returns the oldest key for a user if OATHPrioritizedModules is not set
function getOldestKeyForUser($userId) {
    // Fetch the keys from the database without an explicit sort order
    $keys = fetchKeysFromDatabase($userId);

    // If no keys are found, return null
    if (empty($keys)) {
        return null;
    }

    // Return the first key as it will be the oldest due to the lack of sorting
    return array_shift($keys);
}

// Helper function to fetch keys from the database
function fetchKeysFromDatabase($userId) {
    // SQL query to fetch keys for the given user ID
    $sql = "SELECT * FROM oath_keys WHERE user_id = :userId";

    // Prepare and execute the query
    $stmt = db_query($sql, ['userId' => $userId]);
    $result = $stmt->fetchAll(PDO::FETCH_ASSOC);

    // Return the fetched keys
    return $result;
}
