class WMCSOpenStackCookbook {
    public const TABLE_VM_CONSOLS = 'wmcs_openstack_vm_consoles';

    /**
     * @var DatabaseConnection
     */
    private $db;

    /**
     * Constructor.
     *
     * @param DatabaseConnection $db Database connection object
     */
    public function __construct(DatabaseConnection $db) {
        $this->db = $db;
    }

    /**
     * Fetches the console URL for a given VM ID.
     *
     * @param int $vmId The ID of the VM
     * @return string|null The console URL or null if not found
     */
    public function getConsoleUrl(int $vmId): ?string {
        $query = "SELECT console_url FROM " . self::TABLE_VM_CONSOLS . " WHERE vm_id = ?";
        $result = $this->db->select($query, [$vmId], __METHOD__, [], IDBAccessObject::READ_LATEST);

        if ($result && $row = $result->fetchRow()) {
            return $row['console_url'];
        }

        return null;
    }
}

